function useReveal(){
  const ref=useRef(null);const[v,setV]=useState(false);
  useEffect(()=>{
    const el=ref.current;if(!el)return;
    const ob=new IntersectionObserver(([e])=>{if(e.isIntersecting){setV(true);ob.disconnect();}},{threshold:0.1});
    ob.observe(el);return()=>ob.disconnect();
  },[]);
  return[ref,v];
}

function Spark({data,color="#e4a4bd",w=130,h=40}){
  const mx=Math.max(...data),mn=Math.min(...data),r=mx-mn||1;
  const pts=data.map((v,i)=>`${(i/(data.length-1))*w},${h-((v-mn)/r)*(h-6)-3}`).join(" ");
  const id="s"+color.replace(/[^a-z0-9]/gi,"");
  return(<svg width={w} height={h} style={{overflow:"visible"}}>
    <defs><linearGradient id={id} x1="0" x2="0" y1="0" y2="1">
      <stop offset="0%" stopColor={color} stopOpacity="0.22"/>
      <stop offset="100%" stopColor={color} stopOpacity="0"/>
    </linearGradient></defs>
    <polyline points={`${pts} ${w},${h} 0,${h}`} fill={`url(#${id})`}/>
    <polyline points={pts} fill="none" stroke={color} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>);
}

